package org.jlinalg.cli;
import java.io.IOException;
import java.util.*;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
import static org.jlinalg.cli.NextflowFiles.*;

class NfcoreHic210RequestTest {
    @Test void readsActualJsonAndRetainsEveryIceNumericLexeme()throws Exception{
        String json=NextflowJson.json(request()).replace("0.02","2.00e-2").replace("0.1","1.00e-1");
        var raw=object(NextflowParameters.parse(json,4194304,100000));var parsed=NfcoreHic210Request.parse(raw);
        for(String key:List.of("ice_filter_low_count_perc","ice_filter_high_count_perc","ice_eps"))assertEquals(object(raw.get("science")).get(key),parsed.science().get(key));
        assertTrue(NextflowJson.json(NfcoreHic210Prepare.recipe("/opt/run",parsed)).contains("2.00e-2"));
        for(String literal:List.of("-0.01","1.01","1e309")){var broken=json.replace("2.00e-2",literal);assertThrows(IOException.class,()->NfcoreHic210Request.parse(object(NextflowParameters.parse(broken,4194304,100000))));}
    }
    static Map<String,Object> request(){
        var result=new LinkedHashMap<String,Object>();result.put("schema_version",1);result.put("pipeline_profile",NfcoreHic210Profile.ID);result.put("engine_profile",NfcoreHic210Profile.ENGINE);for(String key:List.of("source_directory","container_home","image_set"))result.put(key,"/private/"+key);result.put("fasta","/reference/whole.fa");result.put("reference_assembly_label","literal-user-assembly");result.put("samples",new ArrayList<>(List.of(new LinkedHashMap<>(Map.of("id","sample+A","libraries",new ArrayList<>(List.of(new LinkedHashMap<>(Map.of("fastq_1","/data/original_R1.fastq.gz","fastq_2","/data/original_R2.fastq.gz")))))))));result.put("executor_cpus",4);result.put("executor_memory_bytes",12884901888L);result.put("task_cpus",2);result.put("task_memory_bytes",4294967296L);result.put("task_seconds",3600);result.put("maximum_reads_per_sample",1000000);result.put("maximum_pairs",1000000);result.put("maximum_bins",1000000);result.put("maximum_pixels",1000000);result.put("maximum_line_characters",1000000);result.put("maximum_decoded_characters",10000000000L);result.put("limits",Map.of());var science=new LinkedHashMap<String,Object>();science.put("digestion","arima");for(String key:List.of("min_restriction_fragment_size","max_restriction_fragment_size","min_insert_size","max_insert_size","min_cis_dist"))science.put(key,0);science.put("min_mapq",10);for(String key:List.of("keep_dups","keep_multi","hicpro_maps"))science.put(key,false);science.put("bin_size","10000,40000,25000,1000000");science.put("res_zoomify","");science.put("res_dist_decay","250000");science.put("res_tads","40000");science.put("res_compartments","250000");science.put("tads_caller","hicexplorer");science.put("ice_max_iter",100);science.put("ice_filter_low_count_perc",0.02);science.put("ice_filter_high_count_perc",0);science.put("ice_eps",0.1);result.put("science",science);return result;
    }
    @SuppressWarnings("unchecked") static Map<String,Object> science(Map<String,Object> r){return(Map<String,Object>)r.get("science");}
    @SuppressWarnings("unchecked") static Map<String,Object> sample(Map<String,Object> r){return((List<Map<String,Object>>)r.get("samples")).get(0);}
    @SuppressWarnings("unchecked") static List<Map<String,Object>> libraries(Map<String,Object> r){return(List<Map<String,Object>>)sample(r).get("libraries");}
    @Test void bindsEveryTechnicalLibraryWithoutInventingSamplesOrChangingIds()throws Exception{var raw=request();libraries(raw).add(new LinkedHashMap<>(Map.of("fastq_1","/data/lib2_R1.fastq.gz","fastq_2","/data/lib2_R2.fastq.gz")));var r=NfcoreHic210Request.parse(raw);assertEquals(1,r.samples().size());var reads=NfcoreHic210Prepare.reads(r);assertEquals(2,reads.size());assertEquals("sample+A",reads.get(1).sample());assertEquals(2,reads.get(1).library());var layout=org.jlinalg.workflow.NfcoreInputBindings.plan("/opt/run/engine","/opt/run/materialized");assertTrue(NfcoreHic210Prepare.samplesheet(r,layout).contains("/workspace/resources/r0/materialized/data/reads/000002/first/lib2_R1.fastq.gz"));}
    @Test void retainsExplicitProtocolCoordinatesAndMapResolutions()throws Exception{var r=NfcoreHic210Request.parse(request());assertEquals("arima",r.science().get("digestion"));assertEquals(10L,r.science().get("min_mapq"));assertEquals(List.of(10000L,40000L,25000L,1000000L,250000L),NfcoreHic210Request.mapResolutions(r));}
    @Test void keepsAllSourceDefaultAnalysisBranchesSelected()throws Exception{var r=NfcoreHic210Request.parse(request());var recipe=NfcoreHic210Prepare.recipe("/opt/run",r);var params=object(recipe.get("parameters"));for(String key:List.of("skip_maps","skip_balancing","skip_mcool","skip_dist_decay","skip_compartments","skip_tads","skip_multiqc"))assertEquals(false,params.get(key));assertEquals(Map.of("$input","bundle","path","data/reference/whole.fa"),params.get("fasta"));assertEquals(true,params.get("igenomes_ignore"));assertFalse(params.containsKey("genome"));assertNull(params.get("res_zoomify"));assertTrue(NfcoreHic210Prepare.outputs(r).contains("tads/hicExplorer"));assertFalse(NfcoreHic210Prepare.outputs(r).contains("tads/insulation"));}
    @Test void rejectsSourceIdentifierRepairAndShellInterpolationCharacters(){for(String id:List.of("sample one","x;other","../x",".")){var r=request();sample(r).put("id",id);assertThrows(IOException.class,()->NfcoreHic210Request.parse(r));}}
    @Test void requiresCompletePairedSourceLibrariesAndExactMateSuffixes(){var missing=request();libraries(missing).get(0).put("fastq_2","");assertThrows(NextflowProcess.Unavailable.class,()->NfcoreHic210Request.parse(missing));var mixed=request();libraries(mixed).get(0).put("fastq_2","/data/read.fq.gz");assertThrows(IOException.class,()->NfcoreHic210Request.parse(mixed));var plain=request();libraries(plain).get(0).put("fastq_1","/data/read.fastq");assertThrows(IOException.class,()->NfcoreHic210Request.parse(plain));}
    @Test void duplicateTechnicalSourceRowsAreNotDroppedToPass(){var r=request();libraries(r).add(new LinkedHashMap<>(libraries(r).get(0)));assertThrows(IOException.class,()->NfcoreHic210Request.parse(r));}
    @Test void doesNotSubstituteEditionDigestionOrUnsupportedOptionalBranches(){var edition=request();edition.put("pipeline_profile","nf-core/hic-latest");assertThrows(NextflowProcess.Unavailable.class,()->NfcoreHic210Request.parse(edition));var digestion=request();science(digestion).put("digestion","dnase");assertThrows(NextflowProcess.Unavailable.class,()->NfcoreHic210Request.parse(digestion));var skip=request();science(skip).put("skip_tads",true);assertThrows(IOException.class,()->NfcoreHic210Request.parse(skip));}
    @Test void capacityConflictsNonfiniteModelsAndImplicitResolutionRepairsRefuseResults(){var cpus=request();cpus.put("task_cpus",5);assertThrows(IOException.class,()->NfcoreHic210Request.parse(cpus));var eps=request();science(eps).put("ice_eps",Double.NaN);assertThrows(IOException.class,()->NfcoreHic210Request.parse(eps));for(String bins:List.of("1000,1000","1kb","1000, 2000","0","2147483648")){var r=request();science(r).put("bin_size",bins);assertThrows(IOException.class,()->NfcoreHic210Request.parse(r));}}
    @Test void originalSourceAndImageImportClosureArePackagedIntact()throws Exception{assertEquals(126,NfcoreHic210Profile.sourceFiles().size());assertEquals(14,NfcoreHic210Profile.images().size());String overlay=NfcoreHic210Profile.overlay("/opt/run/engine","/opt/run/engine/workspace/resources/r0/materialized",4,12884901888L);assertTrue(overlay.contains("withName: 'BOWTIE2_ALIGN_TRIMMED'"));assertTrue(overlay.contains("env.MPLCONFIGDIR = '.matplotlib'"));assertTrue(overlay.contains("/resources/r0/materialized/images/"));}
}
